import json,hashlib,runpy,shutil
from pathlib import Path
r=Path.cwd();v=r/'variants/full-size-pico';sx=runpy.run_path('scripts/kicad-sexpr.py');c=sx['children'];o=sx['one'];pcb=v/'kicad/SeedSigner-Plus-smartcard-pico.kicad_pcb';tree=sx['parse'](pcb.read_text());f=next(f for f in c(tree,'footprint') if any(p[1:3]==['Reference','U202'] for p in c(f,'property')));nets={int(p[1]):o(p,'net')[-1] for p in c(f,'pad')}
names=['GPIO1_B2 / UART2 TX','GPIO1_B3 / UART2 RX','GND','GPIO1_C7','GPIO1_C6','GPIO1_C5','GPIO1_C4','GND','GPIO1_D2 / I2C3 SDA','GPIO1_D3 / I2C3 SCL','GPIO1_A2','GPIO1_C0 / SPI0 CS0','GND','GPIO1_C1 / SPI0 CLK','GPIO1_C2 / SPI0 MOSI','GPIO1_C3 / SPI0 MISO','GPIO0_A4','GND','GPIO1_D0','GPIO1_D1','GPIO4_B1 / Plus GPIO3_A6','GPIO4_B0 / Plus GPIO3_A7','GND','GPIO4_A6 / Plus GPIO3_A5','GPIO4_A2 / Plus GPIO3_A4','GPIO4_A3 / Plus GPIO3_A2','GPIO4_A4 / Plus GPIO3_A3','GND','NC / Plus GPIO3_A1','NC','GPIO4_C0 / ADC0','GPIO4_C1 / ADC1','GND','NC','NC','3V3 OUT','3V3 EN','GND','VSYS','VBUS']
use={'UART_TX':'Reader UART transmit','UART_RX':'Reader UART receive','GND':'Common ground','JoystickDown':'Down button','JoystickPress':'Press / OK button','Key3':'Key 3 button','LCD_DC':'LCD data / command','I2C-SDA':'Unused I2C SDA','I2C-SCL':'Unused I2C SCL','Net-(JP203-B)':'LCD chip select through straps','LCD_SCLK':'LCD SPI clock','LCD_MOSI':'LCD SPI data','LCD_RST':'LCD reset · GPIO, not MISO','JoystickRight':'Right button','JoystickLeft':'Left button','JoystickUp':'Up button','Key1':'Key 1 button','Key2':'Key 2 button','+3.3V':'Backlight enable supply','+5V':'Carrier 5V input'}
pins=[{'pin':i,'name':name,'net':nets[i],'use':use.get(nets[i],'Not connected on carrier'),'function':'POWER' if name in ['GND','3V3 OUT','3V3 EN','VSYS','VBUS'] else 'GPIO' if 'GPIO' in name else 'NC'} for i,name in enumerate(names,1)]
(v/'web-pinout.json').write_text(json.dumps({'title':'Full-size Luckfox Pico / Pico Plus','orientation':'Component side, USB at top; pins 1–20 down left and 40–21 down right.','boardSha256':hashlib.sha256(pcb.read_bytes()).hexdigest(),'pins':pins},indent=2)+'\n')
for side in ['top','bottom']:shutil.copyfile(v/f'manufacturing/gerber-{side}.svg',v/f'pcb-{side}.svg')
